#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    long long w, m;
    std::cin >> w >> m;
    if (w <= 3) {
        std::cout << "YES" << std::endl;
        return 0;
    }
    int nDigits = 0;
    long long power = 1;
    std::vector<long long> bases;
    while (power <= 2000000000LL) {
        bases.push_back(power);
        power *= w;
        nDigits++;
    }
    std::vector<int> counts(nDigits, -1);
    long long sum = 0;
    for (int i = 0; i < nDigits; ++i) {
        sum -= bases[i];
    }
    bool found = false;
    outer:
    while (true) {
        int index = 0;
        while (true) {
            counts[index]++;
            sum += bases[index];
            if (counts[index] != 2) {
                if (std::abs(sum) == m) {
                    found = true;
                }
                break;
            }
            counts[index] = -1;
            sum -= 3 * bases[index];
            index++;
            if (index == nDigits) break outer;
        }
    }
    std::cout << (found ? "YES" : "NO") << std::endl;
    return 0;
}
